mapper.select:
select s.id, s.season_id as seasonId, se.season_name as seasonName, s.stage_id as stageId, st.stage_name as stageName, s.group_id as groupId, g.group_name as groupName, s.team_id as teamId, t.team_no as teamNo, t.team_name as teamName, t.short_name as shortName, lf.access_url as logoUrl, s.rank_no as rankNo, s.matches_played as matchesPlayed, s.wins, s.losses, s.points_for as pointsFor, s.points_against as pointsAgainst, s.point_diff as pointDiff, s.standing_points as standingPoints, s.win_rate as winRate, s.streak_type as streakType, s.streak_count as streakCount, s.qualified_flag as qualifiedFlag, s.snapshot_time as snapshotTime from basket_stage_standing s left join basket_tournament_season se on se.id = s.season_id and se.is_delete = 0 left join basket_tournament_stage st on st.id = s.stage_id and st.is_delete = 0 left join basket_tournament_group g on g.id = s.group_id and g.is_delete = 0 left join basket_team t on t.id = s.team_id and t.is_delete = 0 left join basket_file_asset lf on lf.id = t.logo_file_id and lf.is_delete = 0 where s.is_delete = 0 and s.season_id = #{seasonId} and s.stage_id = #{stageId} and s.group_id = #{groupId} and s.team_id = #{teamId}
and (t.team_name like concat('%', #{teamName}, '%') or t.short_name like concat('%', #{teamName}, '%'))
order by s.season_id, s.stage_id, s.group_id, s.rank_no, s.team_id

mapper.delete:
delete from basket_stage_standing
where season_id = #{seasonId}
and stage_id = #{stageId}
and group_id = #{groupId}

mapper.select:
select id from basket_tournament_group
where is_delete = 0 and stage_id = #{stageId}
order by sequence_no, id

select id from basket_tournament_stage
where is_delete = 0 and season_id = #{seasonId}
order by sequence_no, id
